    def mark(self, arg):
        self.occ[arg.id]=self.occ.get(arg.id,0)+1
        self.present.add(arg.id)
    def add_vals(self, arg, vals):
        self.values.setdefault(arg.id, []).extend(vals)
    def get(self, argid):
        v=self.values.get(argid)
        return v[0] if v else None
    def get_all(self, argid):
        return list(self.values.get(argid, []))

    # flag-like check
    def is_flag_like(self, tok):
        return len(tok)>1 and tok[0]=='-'

    def raise_unknown_long(self, name):
        # own suggestion
        cand_longs=[]
        cand_by_long={}
        for a in self.ctx.args:
            if a.long:
                cand_longs.append(a.long); cand_by_long[a.long]=a.id
        cand=did_you_mean(lossy(name), cand_longs)
        if cand:
            make_unknown(self, f"--{lossy(name)}", suggestion_id=cand_by_long[cand], suggestion_long=cand)
        if self.ctx_key=='top':
            sub=self.find_sub_flag_suggestion(name)
            if sub:
                make_unknown(self, f"--{lossy(name)}", sub_sugg=sub)
        make_unknown(self, f"--{lossy(name)}")

    def find_sub_flag_suggestion(self, name):
        remaining=self.tokens[self.i+1:]
        for tok in remaining:
            if tok in CANON_ORDER and tok!='help':
                subctx=CTXS[tok]
                longs=[a.long for a in subctx.args if a.long]
                cand=did_you_mean(lossy(name), longs)
                if cand:
                    return (cand, tok)
        return None

    def process_long(self, token):
        raw = token.lstrip('-')
        if '=' in raw:
            name, eqval = raw.split('=', 1)
        else:
            name, eqval = raw, None
        if has_surrogates(name):
            raise_panic(PANIC_PARSER, "unexpected invalid UTF-8 code point")
        if name=='help':
            raise ShowHelp(self.ctx_key, long=True)
        if name=='version':
            raise ShowVersion(self.ctx_key)
        arg=self.ctx.by_long.get(name)
        if arg is None or arg.id in ('help','version'):
            self.raise_unknown_long(name)
        self.mark(arg)
        if arg.kind=='flag':
            return
        # option / multi
        if eqval is not None:
            self.add_vals(arg, [eqval.lstrip('=')])
            return
        if arg.kind=='multi':
            self.consume_multi(arg)
        else:
            self.consume_single(arg)

    def process_short(self, token):
        chars=token[1:]
        idx=0
        while idx < len(chars):
            ch=chars[idx]
            if ch=='h':
                raise ShowHelp(self.ctx_key, long=False)
            if ch=='V':
                raise ShowVersion(self.ctx_key)
            arg=self.ctx.by_short.get(ch)
            if arg is None or arg.id in ('help','version'):
                make_unknown(self, f"-{lossy(ch)}")
            self.mark(arg)
            if arg.kind=='flag':
                idx+=1
                continue
            rest=chars[idx+1:]
            if rest:
                eqform=rest.startswith('=')
                val=rest.lstrip('=') if eqform else rest
                self.add_vals(arg, [val])
                if arg.kind=='multi' and not eqform:
                    self.consume_multi(arg)
            else:
                if arg.kind=='multi':
                    self.consume_multi(arg)
                else:
                    self.consume_single(arg)
            break

    def process_flag_token(self, token):
        if token.startswith('--'):
            self.process_long(token)
        else:
            self.process_short(token)

    def consume_single(self, arg):
        if self.i+1 >= len(self.tokens):
            return
        nxt=self.tokens[self.i+1]
        if nxt=='--' or self.is_flag_like(nxt):
            return
        self.i+=1
        self.add_vals(arg, [nxt])

    def consume_multi(self, arg):
        while self.i+1 < len(self.tokens):
            nxt=self.tokens[self.i+1]
            if nxt=='--' or self.is_flag_like(nxt):
                break
            self.i+=1
            self.add_vals(arg, [nxt])

    def assign_positional(self, token):
        for pid in self.ctx.pos_ids:
            arg=self.ctx.by_id[pid]
            vals=self.values.get(pid, [])
            if not vals:
                self.mark(arg); self.add_vals(arg, [token]); return
            if arg.multiple:
                self.add_vals(arg, [token]); return
        make_unknown(self, lossy(token))

    def run_generic(self):
        while self.i < len(self.tokens):
            token=self.tokens[self.i]
            if self.after_sep:
                self.assign_positional(token)
            elif token=='--':
                self.after_sep=True
            elif self.is_flag_like(token):
                self.process_flag_token(token)
            else:
                self.assign_positional(token)
            self.i+=1
        return self

