# ---------- TOML ----------
class TomlError(Exception):
    pass

class DatetimeVal:
    def __init__(self, raw): self.raw=raw

class TomlArray(list):
    def __init__(self, *a, is_array_table=False):
        super().__init__(*a); self.is_array_table=is_array_table

class Table:
    def __init__(self, origin='implicit', line=1):
        self.origin=origin
        self.explicit=False
        self.def_line=line
        self.items=[]  # ('entry',key,value) ('duplicate',key,value) ('redefine',key,path,line,newtable)
        self.map={}
        self.entry_line={}

BARE_RE = re.compile(r'[A-Za-z0-9_-]+')

def type_category(v):
    if isinstance(v, bool): return 'bool'
    if isinstance(v, str): return 'string'
    if isinstance(v, int): return 'integer'
    if isinstance(v, float): return 'float'
    if isinstance(v, DatetimeVal): return 'datetime'
    if isinstance(v, list): return 'array'
    if isinstance(v, Table): return 'table'
    return 'unknown'

def type_desc(v):
    if isinstance(v, str): return f"string {rust_string_debug(v)}"
    if isinstance(v, bool): return f"boolean `{str(v).lower()}`"
    if isinstance(v, int): return f"integer `{v}`"
    if isinstance(v, float): return f"floating point `{rust_float_display(v)}`"
    if isinstance(v, DatetimeVal): return "map"
    if isinstance(v, list): return "sequence"
    if isinstance(v, Table): return "map"
    return "unknown"

class TomlParser:
    def __init__(self, text):
        self.s=text; self.n=len(text); self.i=0; self.line=1
        self.root=Table(origin='root', line=1)
    def err(self, msg):
        raise TomlError(msg)
    def peek(self, off=0):
        j=self.i+off
        return self.s[j] if j<self.n else None
    def advance(self):
        c=self.s[self.i]; self.i+=1
        if c=='\n': self.line+=1
        return c
    def skip_inline(self):
        while self.i<self.n and self.s[self.i] in (' ', '\t'):
            self.i+=1
    # token classification for error messages; raises TomlError
    def classify(self):
        self.skip_inline()
        if self.i>=self.n:
            return ('eof', 'eof', self.line)
        c=self.s[self.i]
        line=self.line
        if c=='\n': return ('newline','a newline',line)
        if c=='\r':
            if self.peek(1)=='\n': return ('newline','a newline',line)
            self.err(f"unexpected character found: `{rust_char_debug(c)}` at line {line}")
        m={
            '[':('left bracket','a left bracket'), ']':('right bracket','a right bracket'),
            '{':('left brace','a left brace'), '}':('right brace','a right brace'),
            '.':('period','a period'), ',':('comma','a comma'), '=':('equals','an equals'),
            ':':('colon','a colon'), '+':('plus','a plus'), '#':('comment','a comment'),
        }
        if c in m:
            return (m[c][0], m[c][1], line)
        if c in ('"', "'"):
            self.parse_string()  # may raise its own errors
            return ('string','a string',line)
        if c.isascii() and (c.isalnum() or c in ('_','-')):
            # identifier
            while self.i<self.n and self.s[self.i].isascii() and (self.s[self.i].isalnum() or self.s[self.i] in ('_','-')):
                self.i+=1
            return ('identifier','an identifier',line)
        self.err(f"unexpected character found: `{rust_char_debug(c)}` at line {line}")
    def expect_error(self, expected_phrase):
        # expected_phrase like "an equals"
        kind, disp, line = self.classify()
        self.err(f"expected {expected_phrase}, found {disp} at line {line}")
    def skip_comment(self):
        while self.i<self.n and self.s[self.i] != '\n':
            self.i+=1
    def expect_eol(self):
        self.skip_inline()
        if self.i>=self.n: return
        c=self.peek()
        if c=='#':
            self.skip_comment()
            if self.i>=self.n: return
            # fallthrough to newline
            c=self.peek()
        if c=='\n':
            self.advance(); return
        if c=='\r' and self.peek(1)=='\n':
            self.i+=1; self.advance(); return
        self.expect_error("newline")
    # ---------- strings ----------
    def parse_string(self):
        q=self.peek(); start_line=self.line
        if self.s[self.i:self.i+3] == q*3:
            return self.parse_multiline_string(q, start_line)
        self.advance()  # opening
        out=[]
        while True:
            if self.i>=self.n:
                self.err(f"unterminated string at line {start_line}")
            c=self.peek()
            if c=='\n' or c=='\r':
                self.err(f"newline in string found at line {self.line}")
            if c==q:
                self.advance(); break
            if q=='"' and c=='\\':
                out.append(self.parse_escape(start_line)); continue
            if (ord(c)<0x20 and c!='\t') or ord(c)==0x7f:
                self.err(f"invalid character in string: `{rust_char_debug(c)}` at line {self.line}")
            out.append(c); self.advance()
        return ''.join(out)
    def parse_multiline_string(self, q, start_line):
        self.i+=3
        # immediate newline trimmed
        if self.peek()=='\r' and self.peek(1)=='\n':
            self.i+=1; self.advance()
        elif self.peek()=='\n':
            self.advance()
        out=[]
        while True:
            if self.i>=self.n:
                self.err(f"unterminated string at line {start_line}")
            if self.s[self.i:self.i+3]==q*3:
                # count consecutive quotes
                cnt=0
                while self.peek(cnt)==q: cnt+=1
                extra=cnt-3
                if extra>0: out.append(q*extra)
                self.i+=cnt
                break
            c=self.peek()
            if q=='"' and c=='\\':
                # line-ending backslash
                j=self.i+1
                # look: spaces/tabs then newline?
                k=j
                while k<self.n and self.s[k] in (' ','\t'): k+=1
                if k<self.n and (self.s[k]=='\n' or (self.s[k]=='\r' and k+1<self.n and self.s[k+1]=='\n')):
                    # skip backslash..newline and all following whitespace incl newlines
                    self.i=k
                    if self.peek()=='\r': self.i+=1
                    self.advance()  # newline
                    while self.i<self.n:
                        ch=self.peek()
                        if ch in (' ','\t'):
                            self.i+=1
                        elif ch=='\n':
                            self.advance()
                        elif ch=='\r' and self.peek(1)=='\n':
                            self.i+=1; self.advance()
                        else:
                            break
                    continue
                out.append(self.parse_escape(start_line)); continue
            if c=='\r':
                if self.peek(1)=='\n':
                    out.append('\n'); self.i+=1; self.advance(); continue
                self.err(f"invalid character in string: `{rust_char_debug(c)}` at line {self.line}")
            if c=='\n':
                out.append('\n'); self.advance(); continue
            if (ord(c)<0x20 and c!='\t') or ord(c)==0x7f:
                self.err(f"invalid character in string: `{rust_char_debug(c)}` at line {self.line}")
            out.append(c); self.advance()
        return ''.join(out)
    def parse_escape(self, start_line):
        # current char is backslash
        self.advance()
        if self.i>=self.n:
            self.err(f"unterminated string at line {start_line}")
        c=self.peek()
        simple={'b':'\b','t':'\t','n':'\n','f':'\f','r':'\r','"':'"', '\\':'\\'}
        if c in simple:
            self.advance(); return simple[c]
        if c in ('u','U'):
            self.advance()
            ndig=4 if c=='u' else 8
            val_str=""
            for _ in range(ndig):
                if self.i>=self.n:
                    self.err(f"unterminated string at line {start_line}")
                h=self.peek()
                if h not in '0123456789abcdefABCDEF':
                    disp = rust_char_debug(h) if not _is_printable(h) else h
                    self.err(f"invalid hex escape character in string: `{disp}` at line {self.line}")
                val_str+=h; self.advance()
            val=int(val_str,16)
            if val>0x10FFFF or 0xD800<=val<=0xDFFF:
                self.err(f"invalid escape value: `{val}` at line {self.line}")
            return chr(val)
        disp = rust_char_debug(c) if not _is_printable(c) or c in ('\n','\r','\t') else c
        self.err(f"invalid escape character in string: `{disp}` at line {self.line}")
    # ---------- keys ----------
    def parse_key_component(self):
        self.skip_inline()
        if self.i>=self.n:
            self.err(f"expected a table key, found eof at line {self.line}")
        c=self.peek()
        if c in ('"', "'"):
            return self.parse_string()
        if c.isascii() and (c.isalnum() or c in ('_','-')):
            m=BARE_RE.match(self.s, self.i)
            self.i=m.end(); return m.group(0)
        self.expect_error("a table key")
    def parse_key_path(self):
        parts=[]
        while True:
            parts.append(self.parse_key_component())
            self.skip_inline()
            if self.peek()=='.':
                self.advance(); continue
            break
        return parts
    # ---------- values ----------
    def parse_value(self):
        self.skip_inline()
        if self.i>=self.n:
            self.err(f"unexpected eof encountered at line {self.line}")
        c=self.peek()
        line=self.line
        if c=='\n' or (c=='\r' and self.peek(1)=='\n') or c=='#' or c in ('.',',',']','}',':'):
            self.expect_error("a value")
        if c=='[':
            return self.parse_array()
        if c=='{':
            return self.parse_inline_table()
        if c in ('"', "'"):
            return self.parse_string()
        # scalar
        return self.parse_scalar()
    def parse_scalar(self):
        start_line=self.line; start=self.i
        while self.i<self.n and self.s[self.i].isascii() and (self.s[self.i].isalnum() or self.s[self.i] in ('_','-','+','.',':')):
            self.i+=1
        token=self.s[start:self.i]
        if token=="":
            # single char like + handled? '+' is in set, so token would be "+". This is for other chars
            c=self.peek()
            self.err(f"unexpected character found: `{rust_char_debug(c)}` at line {self.line}")
        # date + space + time
        if re.fullmatch(r'\d+-\d+-\d+', token):
            # lookahead spaces then time
            save_i, save_line = self.i, self.line
            j=self.i
            while j<self.n and self.s[j]==' ':
                j+=1
            if j>self.i and j<self.n:
                m=re.match(r'\d+:\d+:\d+(?:\.\d+)?(?:[Zz]|[+-]\d+:\d+)?', self.s[j:])
                if m:
                    # ensure following char is delimiter/end
                    end=j+m.end()
                    if end>=self.n or self.s[end] in (' ','\t','\n','\r',',',']','}','#'):
                        self.i=end
                        token=self.s[start:self.i]
                    else:
                        self.i, self.line = save_i, save_line
                # else keep date only
        return self.interpret_scalar(token, start_line)
    def interpret_scalar(self, token, line):
        if token=='true': return True
        if token=='false': return False
        # datetime attempts
        dt=self.try_datetime(token, line)
        if dt is not None:
            return dt
        # number
        num=self.try_number(token, line)
        if num is not None:
            return num
        self.err(f"invalid number at line {line}")
    def try_datetime(self, token, line):
        # time with missing seconds: e.g. 07:32 followed by delimiter
        if re.fullmatch(r'\d+:\d+', token):
            # parser expects another colon
            kind, disp, ln = self.classify_at_current()
            self.err(f"expected a colon, found {disp} at line {ln}")
        if re.fullmatch(r'\d+:\d+:\d+\.', token) or re.fullmatch(r'\d+-\d+-\d+[Tt ].*\.', token):
            self.err(f"invalid date at line {line}")
        date_pat=r'\d+-\d+-\d+'
        time_pat=r'\d+:\d+:\d+(?:\.\d+)?'
        if re.fullmatch(date_pat, token):
            return DatetimeVal(token)
        if re.fullmatch(time_pat, token):
            return DatetimeVal(token)
        if re.fullmatch(date_pat + r'(?:[Tt]|\s+)' + time_pat + r'(?:[Zz]|[+-]\d+:\d+)?', token):
            return DatetimeVal(token)
        # incomplete datetime forms
        if re.match(r'^\d+-\d+-\d+[Tt]', token) or re.match(r'^\d+-\d+-\d+\s+\d', token):
            self.err(f"invalid date at line {line}")
        return None
    def classify_at_current(self):
        # don't consume strings etc (position is at delimiter)
        if self.i>=self.n: return ('eof','eof',self.line)
        c=self.peek()
        if c=='\n': return ('newline','a newline',self.line)
        if c=='\r' and self.peek(1)=='\n': return ('newline','a newline',self.line)
        m={']':'a right bracket','}':'a right brace',',':'a comma','[':'a left bracket','{':'a left brace','.':'a period','=':'an equals',':':'a colon','+':'a plus','#':'a comment'}
        if c in m: return ('x', m[c], self.line)
        if c in ('"',"'"): return ('x','a string',self.line)
        return ('x','an identifier',self.line)
    def try_number(self, token, line):
        t=token
        # inf/nan
        for pat, val in [(r'[+-]?inf', None), (r'[+-]?nan', None)]:
            if re.fullmatch(pat, t):
                sign = -1.0 if t.startswith('-') else 1.0
                return math.copysign(math.inf, sign) if 'inf' in t else math.nan
        # base-prefixed
        m=re.fullmatch(r'(\+?)0([xob])([0-9A-Za-z_]+)', t)
        if m:
            base={'x':16,'o':8,'b':2}[m.group(2)]
            digits=m.group(3)
            valid_chars='0123456789abcdefABCDEF' if base==16 else ('01234567' if base==8 else '01')
            if not self._valid_underscored(digits, valid_chars):
                return None
            val=int(digits.replace('_',''), base)
            if val>0x7FFFFFFFFFFFFFFF:
                return None
            return val
        if re.match(r'[+-]?0[xobX]', t):
            return None
        # decimal int/float
        # reject leading + / - handled
        sign=1
        body=t
        if body.startswith(('+','-')):
            body=body[1:]
            if body=="" : return None
        is_float = ('.' in body) or ('e' in body) or ('E' in body)
        if not is_float:
            if not self._valid_underscored(body, '0123456789'):
                return None
            if len(body.replace('_',''))>1 and body.lstrip('_').startswith('0') and not body.startswith('0_'):
                # leading zero check: integer part starting with 0 and more digits
                digits=body.replace('_','')
                if len(digits)>1 and digits[0]=='0':
                    return None
            val=int(body.replace('_',''))
            if t.startswith('-'): val=-val
            if val>0x7FFFFFFFFFFFFFFF or val< -0x8000000000000000:
                return None
            return val
        else:
            # float pattern
            fm=re.fullmatch(r'(\d(?:[\d_]*\d)?)(?:\.(\d(?:[\d_]*\d)?))?(?:[eE]([+-]?\d(?:[\d_]*\d)?))?', body)
            if not fm: return None
            intpart=fm.group(1)
            if intpart is None: return None
            digits=intpart.replace('_','')
            if len(digits)>1 and digits[0]=='0': return None
            if not self._valid_underscored(intpart, '0123456789'): return None
            if fm.group(2) is not None and not self._valid_underscored(fm.group(2),'0123456789'): return None
            if fm.group(3) is not None and not self._valid_underscored(fm.group(3),'0123456789'): return None
            try:
                return float(t.replace('_',''))
            except Exception:
                return None
    def _valid_underscored(self, s, charset):
        if s=="" or s.startswith('_') or s.endswith('_') or '__' in s: return False
        return all(c in charset or c=='_' for c in s)
    def parse_array(self):
        self.advance()  # [
        arr=TomlArray()
        first_cat=None
        while True:
            self.skip_array_space()
            if self.i>=self.n:
                self.err(f"unexpected eof encountered at line {self.line}")
            if self.peek()==']':
                self.advance(); break
            elem_line=self.line
            val=self.parse_value()
            cat=type_category(val)
            if first_cat is None: first_cat=cat
            elif cat!=first_cat:
                self.err(f"mixed types in an array at line {elem_line}")
            arr.append(val)
            self.skip_array_space()
            if self.i>=self.n:
                # expecting ] or ,
                self.expect_error("a right bracket")
            if self.peek()==',':
                self.advance(); continue
            if self.peek()==']':
                self.advance(); break
            self.expect_error("a right bracket")
        return arr
    def skip_array_space(self):
        while self.i<self.n:
            c=self.peek()
            if c in (' ','\t'):
                self.i+=1
            elif c=='\n':
                self.advance()
            elif c=='\r' and self.peek(1)=='\n':
                self.i+=1; self.advance()
            elif c=='#':
                self.skip_comment()
            else:
                break
    def parse_inline_table(self):
        self.advance()  # {
        tbl=Table(origin='inline', line=self.line)
        self.skip_inline()
        if self.i>=self.n:
            self.err(f"expected a table key, found eof at line {self.line}")
        if self.peek()=='}':
            self.advance(); return tbl
        while True:
            # newline not allowed: parse_key_component handles classify (newline -> expected table key)
            path=self.parse_key_path()
            self.skip_inline()
            if self.i>=self.n or self.peek()!='=':
                self.expect_error("an equals")
            self.advance()
            val=self.parse_value()
            self.insert_keyval(tbl, path, val, self.line)
            self.skip_inline()
            if self.i>=self.n:
                self.expect_error("a comma")
            if self.peek()==',':
                self.advance(); self.skip_inline(); continue
            if self.peek()=='}':
                self.advance(); break
            self.expect_error("a comma")
        return tbl
    # ---------- insertion ----------
    def insert_keyval(self, table, path, value, line):
        target=table
        for comp in path[:-1]:
            if comp not in target.map:
                child=Table(origin='dotted', line=line)
                target.map[comp]=child; target.items.append(('entry',comp,child)); target.entry_line[comp]=line
                target=child
            else:
                existing=target.map[comp]
                if isinstance(existing, Table):
                    if existing.origin=='inline':
                        self.err(f"dotted key attempted to extend non-table type at line {target.entry_line.get(comp, existing.def_line)}")
                    target=existing
                elif isinstance(existing, TomlArray) and existing.is_array_table and len(existing)>0:
                    target=existing[-1]
                else:
                    self.err(f"dotted key attempted to extend non-table type at line {target.entry_line.get(comp, line)}")
        last=path[-1]
        if last in target.map:
            target.items.append(('duplicate',last,value))
        else:
            target.map[last]=value; target.items.append(('entry',last,value)); target.entry_line[last]=line
    def parse_header(self):
        start_line=self.line
        self.advance()  # [
        is_array=False
        if self.peek()=='[':
            is_array=True; self.advance()
        path=self.parse_key_path()
        self.skip_inline()
        if self.i>=self.n or self.peek()!=']':
            self.expect_error("a right bracket")
        self.advance()
        if is_array:
            if self.i>=self.n or self.peek()!=']':
                self.expect_error("a right bracket")
            self.advance()
        # navigate
        target=self.root
        for comp in path[:-1]:
            if comp not in target.map:
                child=Table(origin='implicit', line=start_line)
                target.map[comp]=child; target.items.append(('entry',comp,child)); target.entry_line[comp]=start_line
                target=child
            else:
                existing=target.map[comp]
                if isinstance(existing, Table):
                    target=existing
                elif isinstance(existing, TomlArray) and existing.is_array_table and len(existing)>0:
                    target=existing[-1]
                else:
                    child=Table(origin='implicit', line=start_line)
                    target.items.append(('redefine',comp,'.'.join(path),start_line,child))
                    target=child
        last=path[-1]
        path_str='.'.join(path)
        if is_array:
            if last not in target.map:
                arr=TomlArray(is_array_table=True); elem=Table(origin='array_table', line=start_line); elem.explicit=True; arr.append(elem)
                target.map[last]=arr; target.items.append(('entry',last,arr)); target.entry_line[last]=start_line
                new_target=elem
            else:
                existing=target.map[last]
                if isinstance(existing, TomlArray) and existing.is_array_table:
                    elem=Table(origin='array_table', line=start_line); elem.explicit=True; existing.append(elem); new_target=elem
                else:
                    elem=Table(origin='array_table', line=start_line)
                    target.items.append(('redefine',last,path_str,start_line,elem)); new_target=elem
            self.expect_eol()
            return new_target
        else:
            if last not in target.map:
                tbl=Table(origin='header', line=start_line); tbl.explicit=True
                target.map[last]=tbl; target.items.append(('entry',last,tbl)); target.entry_line[last]=start_line
                new_target=tbl
            else:
                existing=target.map[last]
                if isinstance(existing, Table):
                    if existing.explicit:
                        tbl=Table(origin='header', line=start_line); tbl.explicit=True
                        target.items.append(('redefine',last,path_str,start_line,tbl)); new_target=tbl
                    else:
                        existing.explicit=True; existing.origin='header'; new_target=existing
                else:
                    tbl=Table(origin='header', line=start_line); tbl.explicit=True
                    target.items.append(('redefine',last,path_str,start_line,tbl)); new_target=tbl
            self.expect_eol()
            return new_target
    def parse_keyval_and_eol(self, table):
        line=self.line
        path=self.parse_key_path()
        self.skip_inline()
        if self.i>=self.n or self.peek()!='=':
            self.expect_error("an equals")
        self.advance()
        val=self.parse_value()
        self.insert_keyval(table, path, val, line)
        self.expect_eol()
    def parse(self):
        if self.s.startswith('\ufeff'):
            self.i=1
        current=self.root
        while True:
            self.skip_inline()
            if self.i>=self.n: break
            c=self.peek()
            if c=='\n':
                self.advance(); continue
            if c=='\r':
                if self.peek(1)=='\n':
                    self.i+=1; self.advance(); continue
                self.err(f"unexpected character found: `{rust_char_debug(c)}` at line {self.line}")
            if c=='#':
                self.skip_comment(); continue
            if c=='[':
                current=self.parse_header(); continue
            self.parse_keyval_and_eol(current)
        return self.root

