# ---------- TOML ----------
class TomlError(Exception):
    pass

class DatetimeVal:
    def __init__(self, raw): self.raw=raw

class TomlArray(list):
    def __init__(self, *a, is_array_table=False):
        super().__init__(*a); self.is_array_table=is_array_table

class Table:
    def __init__(self, origin='implicit', line=1):
        self.origin=origin
        self.explicit=False
        self.def_line=line
        self.items=[]  # ('entry',key,value) ('duplicate',key,value) ('redefine',key,path,line,newtable)
        self.map={}
        self.entry_line={}

BARE_RE = re.compile(r'[A-Za-z0-9_-]+')

def type_category(v):
    if isinstance(v, bool): return 'bool'
    if isinstance(v, str): return 'string'
    if isinstance(v, int): return 'integer'
    if isinstance(v, float): return 'float'
    if isinstance(v, DatetimeVal): return 'datetime'
    if isinstance(v, list): return 'array'
    if isinstance(v, Table): return 'table'
    return 'unknown'

def type_desc(v):
    if isinstance(v, str): return f"string {rust_string_debug(v)}"
    if isinstance(v, bool): return f"boolean `{str(v).lower()}`"
    if isinstance(v, int): return f"integer `{v}`"
    if isinstance(v, float): return f"floating point `{rust_float_display(v)}`"
    if isinstance(v, DatetimeVal): return "map"
    if isinstance(v, list): return "sequence"
    if isinstance(v, Table): return "map"
    return "unknown"

class TomlParser:
    def __init__(self, text):
        self.s=text; self.n=len(text); self.i=0; self.line=1
        self.root=Table(origin='root', line=1)
    def err(self, msg):
        raise TomlError(msg)
    def peek(self, off=0):
        j=self.i+off
        return self.s[j] if j<self.n else None
    def advance(self):
        c=self.s[self.i]; self.i+=1
        if c=='\n': self.line+=1
        return c
    def skip_inline(self):
        while self.i<self.n and self.s[self.i] in (' ', '\t'):
            self.i+=1
    # token classification for error messages; raises TomlError
    def classify(self):
        self.skip_inline()
        if self.i>=self.n:
            return ('eof', 'eof', self.line)
        c=self.s[self.i]
        line=self.line
        if c=='\n': return ('newline','a newline',line)
        if c=='\r':
            if self.peek(1)=='\n': return ('newline','a newline',line)
            self.err(f"unexpected character found: `{rust_char_debug(c)}` at line {line}")
        m={
            '[':('left bracket','a left bracket'), ']':('right bracket','a right bracket'),
            '{':('left brace','a left brace'), '}':('right brace','a right brace'),
