def validate_default_value(value, ctx, field_full, cfg):
    if isinstance(value, Table):
        seen=set()
        for item in value.items:
            if item[0]=='redefine':
                raise TomlError(f"redefinition of table `{item[2]}` for key `{item[2]}` at line {item[3]}")
            key=item[1]; v=item[2]; is_dup=(item[0]=='duplicate')
            if key in ('interpreter','command_width'):
                if is_dup:
                    raise TomlError(f"duplicate field `{key}` for key `{ctx}`")
                seen.add(key)
                flabel=f"{ctx}.{key}" if field_full else ctx
                if key=='interpreter':
                    if not isinstance(v, list):
                        raise TomlError(f"invalid type: {type_desc(v)}, expected a sequence for key `{flabel}`")
                    for el in v:
                        if not isinstance(el, str):
                            raise TomlError(f"invalid type: {type_desc(el)}, expected a string for key `{flabel}`")
                    cfg.interpreter=list(v)
                else:
                    if isinstance(v, int) and not isinstance(v, bool):
                        if v<0:
                            raise TomlError(f"invalid value: integer `{v}`, expected usize for key `{flabel}`")
                        cfg.command_width=v
                    else:
                        raise TomlError(f"invalid type: {type_desc(v)}, expected usize for key `{flabel}`")
            else:
                ensure_no_redefine(v)
        return
    elif isinstance(value, list):
        if len(value)==0:
            raise TomlError(f"invalid length 0, expected struct ConfigDefaultOpts with 2 elements for key `{ctx}`")
        e0=value[0]
        if not isinstance(e0, list):
            raise TomlError(f"invalid type: {type_desc(e0)}, expected a sequence for key `{ctx}`")
        if len(value)==1:
            raise TomlError(f"invalid length 1, expected struct ConfigDefaultOpts with 2 elements for key `{ctx}`")
        e1=value[1]
        if not (isinstance(e1,int) and not isinstance(e1,bool) and e1>=0):
            if isinstance(e1,int) and not isinstance(e1,bool) and e1<0:
                raise TomlError(f"invalid value: integer `{e1}`, expected usize for key `{ctx}`")
            raise TomlError(f"invalid type: {type_desc(e1)}, expected usize for key `{ctx}`")
        return
    else:
        raise TomlError(f"invalid type: {type_desc(value)}, expected struct ConfigDefaultOpts for key `{ctx}`")

def validate_config(root):
    cfg=ConfigObj()
    for item in root.items:
        if item[0]=='redefine':
            raise TomlError(f"redefinition of table `{item[2]}` for key `{item[2]}` at line {item[3]}")
        key=item[1]; v=item[2]; is_dup=(item[0]=='duplicate')
        if key=='scripts':
            if is_dup:
                raise TomlError("duplicate field `scripts`")
            if not isinstance(v, Table):
                raise TomlError(f"invalid type: {type_desc(v)}, expected map is expected for key `scripts`")
            # scripts table
            inline_parent = (v.origin=='inline')
            for sitem in v.items:
                if sitem[0]=='redefine':
                    raise TomlError(f"redefinition of table `{sitem[2]}` for key `{sitem[2]}` at line {sitem[3]}")
                alias=sitem[1]; sval=sitem[2]
                sctx = "scripts" if inline_parent else f"scripts.{alias}"
                field_full = isinstance(sval, Table) and sval.origin=='header'
                script=validate_script_value(sval, sctx, field_full)
                cfg.scripts[alias]=script
        elif key=='default':
            if is_dup:
                raise TomlError("duplicate field `default`")
            field_full = isinstance(v, Table) and v.origin=='header'
            validate_default_value(v, "default", field_full, cfg)
        else:
            ensure_no_redefine(v)
    return cfg

def load_config_from_text(text):
    root=TomlParser(text).parse()
    return validate_config(root)

# ---------- TOML serialization ----------
def escape_basic(s, multiline=False):
    out=[]
    for c in s:
        if c=='"': out.append('\\"')
        elif c=='\\': out.append('\\\\')
        elif c=='\b': out.append('\\b')
        elif c=='\f': out.append('\\f')
        elif c=='\n':
            out.append('\n' if multiline else '\\n')
        elif c=='\r': out.append('\\r')
        elif c=='\t': out.append('\\t')
        elif ord(c)<0x20:
            out.append("\\u%04X" % ord(c))
        else:
            out.append(c)
    return ''.join(out)

def toml_string_repr(s):
    has_nl='\n' in s
    bad_control=any((ord(c)<0x20 and c not in ('\t','\n')) for c in s)
    if has_nl:
        if bad_control or "'''" in s or s.endswith("'"):
            return '"""\n' + escape_basic(s, multiline=True) + '"""'
        return "'''\n" + s + "'''"
    else:
        if bad_control or "'''" in s or s.endswith("'"):
            return '"' + escape_basic(s, multiline=False) + '"'
        if "'" in s:
            return "'''" + s + "'''"
        return "'" + s + "'"

def toml_key_repr(k):
    if k!="" and all(c.isascii() and (c.isalnum() or c in ('_','-')) for c in k):
        return k
    if k=="":
        return ""
    return '"' + escape_basic(k, multiline=False) + '"'

def toml_array_repr(vals):
    if len(vals)==0:
        return "[]"
    if len(vals)==1:
        return "[" + toml_string_repr(vals[0]) + "]"
    parts=["[\n"]
    for v in vals:
        parts.append("    " + toml_string_repr(v) + ",\n")
    parts.append("]")
    return ''.join(parts)

def serialize_config(cfg):
    parts=[]
    if cfg.scripts:
        for alias in sorted(cfg.scripts.keys()):
            sc=cfg.scripts[alias]
            parts.append(f"[scripts.{toml_key_repr(alias)}]\n")
            parts.append(f"command = {toml_string_repr(sc.command)}\n")
            if sc.description is not None:
                parts.append(f"description = {toml_string_repr(sc.description)}\n")
            if sc.tags is not None:
                parts.append(f"tags = {toml_array_repr(sc.tags)}\n")
            parts.append("\n")
    else:
        parts.append("[scripts]\n\n")
    parts.append("[default]\n")
    if cfg.interpreter is not None:
        parts.append(f"interpreter = {toml_array_repr(cfg.interpreter)}\n")
    if cfg.command_width is not None:
        parts.append(f"command_width = {cfg.command_width}\n")
    return ''.join(parts)

# ---------- config paths ----------
def home_dir():
    h=os.environ.get("HOME")
    if h:
        return h
    try:
        import pwd
        pw=pwd.getpwuid(os.getuid())
        if pw.pw_dir:
            return pw.pw_dir
    except Exception:
        pass
    return None

def config_dir():
    x=os.environ.get("XDG_CONFIG_HOME")
    if x and os.path.isabs(x):
        return x
    h=home_dir()
    if h is not None:
        return os.path.join(h, ".config")
    return None

def candidate_paths():
    cands=["pier.toml"]
    cd=config_dir()
    if cd is not None:
        cands.append(os.path.join(cd, "pier", "config.toml"))
        cands.append(os.path.join(cd, "pier", "config"))
        cands.append(os.path.join(cd, "pier.toml"))
    h=home_dir()
    if h is not None:
        cands.append(os.path.join(h, ".pier.toml"))
        cands.append(os.path.join(h, ".pier"))
    return cands

def find_existing_candidate():
    for c in candidate_paths():
        if os.path.exists(c):
            return c
    return None

def read_config_file(path):
    try:
        with open(path, 'rb') as f:
            data=f.read()
    except OSError as e:
        raise AppError(f"Unable to read config from file {path}: {rust_io_error(e)} ")
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError:
        raise AppError(f"Unable to read config from file {path}: stream did not contain valid UTF-8 ")
    try:
        return load_config_from_text(text)
    except TomlError as e:
        raise AppError(f"Unable to parse toml config from file {path}: {e}")

def write_config_file(path, cfg):
    text=serialize_config(cfg)
    try:
        with open(path, 'wb') as f:
            f.write(text.encode('utf-8'))
    except OSError as e:
        raise AppError(f"Unable to write config to {path}: {rust_io_error(e)}")
    except ValueError as e:
        raise AppError(f"Unable to write config to {path}: {e}")

def rust_parent(path):
    if path=="":
        return None
    p=path.rstrip('/')
    if p=="":
        return None  # path was "/" or "///"
    idx=p.rfind('/')
    if idx<0:
        return ""
    if idx==0:
        return "/"
    return p[:idx]

