def do_list(cfg, sub):
    check_scripts(cfg)
    tag_present = sub.occ.get('tag',0)>0
    filter_tags = sub.get_all('tag') if tag_present else None
    entries=[]  # list of (alias, script)
    for alias in sorted(cfg.scripts.keys()):
        sc=cfg.scripts[alias]
        if filter_tags is None:
            entries.append((alias, sc))
        else:
            if sc.tags is None:
                continue
            count=0
            for ft in filter_tags:
                for st in sc.tags:
                    if ft==st: count+=1
            for _ in range(count):
                entries.append((alias, sc))
    if sub.occ.get('list_aliases',0)>0:
        for alias, sc in entries:
            out_text(alias+"\n")
        return 0
    # command display
    cli_width=None
    if sub.occ.get('cmd_width',0)>0:
        cli_width, _e = parse_usize_value(sub.get('cmd_width'))
    rows=[]
    for alias, sc in entries:
        if sub.occ.get('cmd_full',0)>0:
            cmd=sc.command
        elif cli_width is not None:
            cmd=first_line(sc.command)[:cli_width]
        elif cfg.command_width is not None:
            cmd=first_line(sc.command)[:cfg.command_width]
        else:
            cmd=first_line(sc.command)[:80]
        tags=",".join(sc.tags) if sc.tags is not None else ""
        desc=sc.description if sc.description is not None else ""
        rows.append([alias, tags, cmd, desc])
