    check_scripts(cfg)
    if alias not in cfg.scripts:
        raise AppError(f"AliasNotFound: No script found by alias {alias}")
    sc=cfg.scripts[alias]
    if cfg.interpreter is not None:
        interp=list(cfg.interpreter)
    else:
        shell=env_var_valid("SHELL")
        if shell is None:
            shell="sh"
        interp=[shell, "-c"]
    if verbose:
        out_text(f"Starting script \"{alias}\"\n-------------------------\n")
    if len(interp)==0:
        raise_panic("src/script.rs:52:44", "index out of bounds: the len is 0 but the index is 0")
    cmd_list=[interp[0]] + interp[1:] + [sc.command, alias] + list(script_args)
    for a in cmd_list:
        if '\x00' in a:
            raise AppError("Command execution failed with: nul byte found in provided data")
    try:
        proc=subprocess.run([os.fsencode(a) for a in cmd_list], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except ValueError:
        raise AppError("Command execution failed with: nul byte found in provided data")
    except OSError as e:
        raise AppError(f"Command execution failed with: {rust_io_error(e)}")
    out_bytes(proc.stdout)
    if proc.stderr:
        err_bytes(proc.stderr + b"\n")
    if verbose:
        out_text("-------------------------\nScript complete\n")
    rc=proc.returncode
    if rc is None: return 0
    if rc<0: return 0
    return rc

