    if cfg_value is not None:
        cfg_path=cfg_value
    else:
        cfg_path=find_existing_candidate()
        if cfg_path is None:
            raise AppError("No default config file found. See help for more info.")
    cfg=read_config_file(cfg_path)

    if plan.kind=='default':
        alias=top.get('alias'); args=top.get_all('args')
        verbose=top.occ.get('verbose',0)>0
        return run_script(cfg, alias, args, verbose)

