        check_scripts(cfg)
        if alias not in cfg.scripts:
            raise AppError(f"AliasNotFound: No script found by alias {alias}")
        newcmd=get_editor_input(cfg.scripts[alias].command)
        cfg.scripts[alias].command=newcmd
        out_text(f"Edited {alias}\n")
        write_config_file(cfg_path, cfg)
        return 0
    if canon=='remove':
        alias=sub.get('alias')
        check_scripts(cfg)
        if alias not in cfg.scripts:
            raise AppError(f"AliasNotFound: No script found by alias {alias}")
        del cfg.scripts[alias]
        out_text(f"Removed {alias}\n")
        write_config_file(cfg_path, cfg)
        return 0
    if canon=='copy':
        frm=sub.get('from_alias'); to=sub.get('to_alias')
        if to in cfg.scripts:
            raise AppError(f"AliasAlreadyExists:  {to}")
        if frm not in cfg.scripts:
            raise AppError(f"AliasNotFound: No script found by alias {frm}")
        src=cfg.scripts[frm]
        cfg.scripts[to]=ScriptObj(src.command, src.description, list(src.tags) if src.tags is not None else None)
        out_text(f"Copy from alias {frm} to new alias {to}\n")
        write_config_file(cfg_path, cfg)
        return 0
    if canon=='move':
        frm=sub.get('from_alias'); to=sub.get('to_alias')
        force=sub.occ.get('force',0)>0
        if (not force) and to in cfg.scripts:
            raise AppError(f"AliasAlreadyExists:  {to}")
        if frm not in cfg.scripts:
            raise AppError(f"AliasNotFound: No script found by alias {frm}")
        src=cfg.scripts[frm]
        copied=ScriptObj(src.command, src.description, list(src.tags) if src.tags is not None else None)
        if frm==to:
            cfg.scripts[to]=copied
        else:
            del cfg.scripts[frm]
            cfg.scripts[to]=copied
        out_text(f"Move from alias {frm} to new alias {to}\n")
        write_config_file(cfg_path, cfg)
        return 0
